const g = globalThis as unknown as {
  __layersMockState?: MutableState;
  __layersHydrated?: Promise<void> | null;
  /** LAYERS_WORLD=empty: what hydrate's partition hid, per namespace, kept verbatim for every write. PROCESS-GLOBAL
   *  on purpose: a route handler and a server render each load this module, and a write from an instance that did
   *  not hydrate must still merge the hidden rows back — a module-local stash would let it write them away. */
  __layersWorldHidden?: Map<string, HiddenPart>;
  /** STRICT_STATE (the empty world, the owner service): this process has read the stored state. No namespace is
   *  written before it has (a write REPLACES the stored namespace, so a write from a store that never read would
   *  delete what it never saw). */
  __layersWorldLoaded?: boolean;
  /** LAYERS_WORLD=empty: the real personas the hydrate partitioned against (the stash's fingerprints are taken
   *  against the same set) */
  __layersWorldReal?: ReadonlySet<string>;
  /** LAYERS_WORLD=empty (review WE-3): keys a write named that the partition had hidden, per namespace — the stored
   *  record was KEPT (lib/world.ts mergeHidden). Counted for the /api/dev world report, logged once per key. */
  __layersWorldCollisions?: Map<string, Set<string>>;
  /** LAYERS_WORLD=empty (review WE-1): every key the partition hid a whole record under, across namespaces — nextId
   *  never hands one of them out, so a new record cannot take a hidden record's key whatever the id format does. */
  __layersWorldHiddenKeys?: Set<string>;
};

/** STRICT_STATE: refuse a namespace write until this process has read the stored state (see above). */
function assertWorldLoaded(ns: string): void {
  if (STRICT_STATE && !g.__layersWorldLoaded)
    throw new Error(
      `store: refusing to write "${ns}" before the stored state was read (${EMPTY_WORLD ? "LAYERS_WORLD=empty" : "owner service"}) — the write would replace rows this process never loaded`
    );
}

/** LAYERS_WORLD=empty: the merge kept a hidden record a write named (review WE-3). Said LOUDLY, once per key —
 *  this process's value for that key lives in memory only; the stored record is the hidden one. No key is printed
 *  (keys can be persona ids): the namespace and a running count. */
function noteCollision(ns: string, key: string): void {
  const m = (g.__layersWorldCollisions ??= new Map());
  const set = m.get(ns) ?? new Set<string>();
  if (set.has(key)) return;
  set.add(key);
  m.set(ns, set);
  console.error(
    `[world] ${ns}: a write named a key whose stored record is HIDDEN under LAYERS_WORLD=empty — the stored record is kept and this process's value is not written over it (key #${set.size} in ${ns}). Delete LAYERS_WORLD to see and edit the stored record.`
  );
}

/** LAYERS_WORLD=empty: how many hidden keys a write has collided with, per namespace (counts only). */
export function worldCollisionCounts(): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [ns, set] of g.__layersWorldCollisions ?? new Map<string, Set<string>>()) out[ns] = set.size;
  return out;
}

/** the merge options for one namespace's write: the CURRENT real personas (a persona created since the hydrate
 *  governs its own elements) and the collision report */
function mergeOpts(ns: string) {
  return { real: new Set(realPersonaIds()), onCollision: (k: string) => noteCollision(ns, k) };
}

function worldHidden(): Map<string, HiddenPart> {
  return (g.__layersWorldHidden ??= new Map());
}

/** LAYERS_WORLD=empty: how many stored entries the partition is holding back, per namespace (counts only — for the
 *  boot line and the empty-world suite; never the entries). */
export function worldHiddenCounts(): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [ns, h] of worldHidden()) out[ns] = h.count;
  return out;
}

/**
 * LAYERS_WORLD=empty — the evidence that hidden means KEPT, entry by entry. Read every namespace AS STORED on the
 * validator right now (a fresh read; no process state touched), partition it against the current real personas, and
 * compare its hidden entries with this process's stash by fingerprint:
 *   missing — stashed at hydrate, no longer stored: a write DROPPED a hidden row (must be 0);
 *   extra   — hidden in what is stored but not in the stash: something written UNDER the flag that the flag would
 *             hide on the next boot (a write about nobody, or about a demo persona) — also must be 0.
 * Counts only; read-only.
 */
export async function worldStoredDiff(): Promise<Record<string, { stash: number; stored: number; missing: number; extra: number }>> {
  if (!EMPTY_WORLD) return {};
  const loaded = await loadAllStrict();
  const real = new Set(realPersonaIds());
  const stashReal = g.__layersWorldReal ?? real;
  const out: Record<string, { stash: number; stored: number; missing: number; extra: number }> = {};
  for (const ns of Object.keys(SERIALIZERS) as Namespace[]) {
    const entries = loaded[ns];
    let storedFp: string[] = [];
    if (entries) {
      const unsealed = unsealAny(ns, entries as Record<string, unknown>);
      const { __seq: _seq, ...rest } = unsealed as Record<string, unknown> & { __seq?: number };
      void _seq;
      storedFp = hiddenFingerprints(ns, partitionNamespace(ns, rest, real).hidden, real);
    }
    const stashFp = hiddenFingerprints(ns, worldHidden().get(ns), stashReal);
    if (!storedFp.length && !stashFp.length) continue;
    const storedSet = new Set(storedFp);
    const stashSet = new Set(stashFp);
    out[ns] = {
      stash: stashFp.length,
      stored: storedFp.length,
      missing: stashFp.filter((f) => !storedSet.has(f)).length,
      extra: storedFp.filter((f) => !stashSet.has(f)).length,
    };
  }
  return out;
}

