g.__layersMockState ??= freshState();

export function state(): MutableState {
  // Self-heal across hot reloads: the global survives HMR, so a state object
  // created before a new field was added would be missing it and blow up at
  // the first access. Backfill any absent key from a fresh baseline.
  const s = g.__layersMockState!;
  const fresh = freshState();
  for (const key of Object.keys(fresh) as (keyof MutableState)[]) {
    if (s[key] === undefined) (s as unknown as Record<string, unknown>)[key] = fresh[key];
  }
  return s;
}

// ---------- (de)serialization per namespace ----------

type Serializer = { dump: (s: MutableState) => Record<string, unknown>; load: (s: MutableState, e: Record<string, any>) => void };

const mapDump = <V>(m: Map<string, V>) => Object.fromEntries(m);
const listDump = <V>(list: V[], key: (v: V, i: number) => string) =>
  Object.fromEntries(list.map((v, i) => [key(v, i), v]));

