/**
 * PERSONA LAUNCH P2 (BYX G1): every SERIALIZERS namespace as persistNs would send it (the dump, plus the `__seq` the
 * whole-sealed writes carry) — read by scripts/unit-namespace-sizes.mjs, which seals each one and asserts it fits the
 * validator's body limit with headroom. Read-only; nothing is flushed.
 */
export function auditNamespaceDumps(): Record<string, { payload: Record<string, unknown>; vault: boolean }> {
  const out: Record<string, { payload: Record<string, unknown>; vault: boolean }> = {};
  const st = state();
  for (const ns of Object.keys(SERIALIZERS) as Namespace[]) {
    const visible = SERIALIZERS[ns].dump(st);
    out[ns] = isVaultNamespace(ns) ? { payload: visible, vault: true } : { payload: { ...visible, __seq: st.seq }, vault: false };
  }
  return out;
}

const OPAQUE_STEP = 1024;
/**
 * PERSONA LAUNCH wave 3 (L4) — THE zkQueue's SIZE IS ONE CONSTANT for every device: ZKQ_CHUNK (64 KiB of plaintext), so
 * the sealed record's ciphertext says nothing about how many anonymous posts, X copies or launches this root ever made
 * nor when (SECURITY-POSTURE PRIV-3). Wave 3 also took the post TEXT off the reveal records (lib/zk/anon/queue.ts: a
 * 128-bit words hash instead), so one chunk holds the in-window submissions (K anon posts, K_X copies, a launch request:
 * ~15 KiB at most) beside about ninety lifetime reveal records. ONE chunk is also the most the validator's 256 KiB body
 * limit takes: it seals to about 128 KiB (scripts/unit-namespace-sizes.mjs: 131,130 bytes, 50% headroom), so a second
 * chunk (~262 KB sealed) is refused by the persist client before it is sent — a device past about ninety lifetime posts
 * cannot persist its queue (A-ZKQUEUE-CAPACITY: the power-of-two classes hit the same wall at 64 KiB, sooner, while the
 * text was kept; the way past it is the queue split over several fixed-size records written on one schedule — the
 * store's follow-up). Below the wall the size never changes, whatever this root did.
 */
export const ZKQ_CHUNK = 64 * 1024;
export function zkQueuePadTarget(innerLength: number): number {
  return ZKQ_CHUNK * Math.max(1, Math.ceil((innerLength + 64) / ZKQ_CHUNK));
}
function opaqueDump(map: Record<string, unknown>, targetOf: (innerLength: number) => number = (n) => OPAQUE_STEP * Math.ceil((n + 64) / OPAQUE_STEP)): Record<string, unknown> {
  const inner = JSON.stringify(map);
  const target = targetOf(inner.length);
  return { _: { m: map, pad: " ".repeat(Math.max(0, target - inner.length - 48)) } };
}
function opaqueLoad(e: Record<string, unknown>): Record<string, unknown> {
  const rec = e?._ as { m?: Record<string, unknown> } | undefined;
  return rec && typeof rec === "object" && rec.m && typeof rec.m === "object" ? rec.m : {};
}

// Last-flushed snapshot per namespace. Several "mutating" methods only
// mutate conditionally — mode.list/getActive seed presets on first call and
// are pure reads thereafter — so without a dirty check every feed build
// would PUT whole namespaces over HTTP. That is both wasteful and enough
// traffic to make the validator connection flaky under a test marathon.
const lastFlushed = new Map<Namespace, string>();
/**
 * PERSONA LAUNCH P2 (review W1-R4): the body of each namespace that is queued or in flight and not yet answered. The
 * dirty check compares against what WILL be stored, not only what last was: a like then an unlike in quick succession
 * dumped S1 (sent, in flight) then S0 — equal to the LAST LANDED body, so the unlike was skipped and S1 landed after it,
 * leaving the validator liked while memory said unliked. A body equal to the in-flight one waits for that flush (and
 * shares its failure) instead of answering at once; any other body queues behind it (flush keeps one body per
 * namespace in flight, in call order — lib/adapters/mock/persist.ts).
 */
const inFlight = new Map<Namespace, { serialized: string; done: Promise<void> }>();

/** Write one namespace through to the validator, if it actually changed. */
export async function persistNs(ns: Namespace): Promise<void> {
  const visible = SERIALIZERS[ns].dump(state());
  const serialized = JSON.stringify(visible);
  const pending = inFlight.get(ns);
  if (pending) {
    if (pending.serialized === serialized) return pending.done; // the body already on its way is this one
  } else if (lastFlushed.get(ns) === serialized) return; // nothing changed — checked on PLAINTEXT
  // LAYERS_WORLD=empty: the write REPLACES the stored namespace, so the entries hydrate hid go back in with it
  // (lib/world.ts mergeHidden) — hidden is never deleted. The demo world: no stash, the dump as it always was.
  assertWorldLoaded(ns);
  const hiddenPart = EMPTY_WORLD ? worldHidden().get(ns) : undefined;
  // PRIV-3: the zkQueue keeps its coarse padding class when LAYERS_WORLD=empty merges hidden entries back in
  const payload = hiddenPart ? mergeHidden(visible, hiddenPart, ns === "zkQueue" ? (m: Record<string, unknown>) => opaqueDump(m, zkQueuePadTarget) : opaqueDump, mergeOpts(ns)) : visible;
  // the flush is CALLED synchronously here (no await before it), so its place in the namespace's queue is this call's
  const done = (
    isVaultNamespace(ns)
      ? // Encrypt AFTER the plaintext dirty-check, and flush LOUD: a vault
        // write that silently fails is invisible data loss. The server only
        // ever sees the ciphertext document.
        flushVault(ns, encryptNamespace(ns, payload))
      : // Review WE-1: the id counter rides along with EVERY whole-sealed write (`__seq`, stripped and restored as the
        // max over all namespaces at hydrate), so a restart continues the count instead of starting at 0 — persistSeq
        // was the only writer of `__seq` and nothing called it. Whole-sealed only: the map is one opaque record, so the
        // extra key changes no stored row count; a vault namespace is sealed per record, and its ids are covered by the
        // next whole-sealed write and by the per-process epoch in nextId.
        flush(ns, { ...payload, __seq: state().seq })
  ).then(() => {
    lastFlushed.set(ns, serialized);
  });
  inFlight.set(ns, { serialized, done });
  try {
    await done;
  } finally {
    if (inFlight.get(ns)?.done === done) inFlight.delete(ns);
  }
}

/** Hydration and reset both invalidate the dirty-check baseline. */
function clearFlushCache() {
  lastFlushed.clear();
}

/** Persist the seq counter with the modes namespace. Review WE-1: superseded — persistNs now carries `__seq` on every
 *  whole-sealed write, so the counter is persisted by the write that consumed it; kept for the callers that may want
 *  the counter written without a content change. */
export async function persistSeq(): Promise<void> {
  const visible = SERIALIZERS.modes.dump(state());
  // LAYERS_WORLD=empty: the hidden modes ride along, exactly as in persistNs
  assertWorldLoaded("modes");
  const hiddenModes = EMPTY_WORLD ? worldHidden().get("modes") : undefined;
  const dump = hiddenModes ? mergeHidden(visible, hiddenModes, opaqueDump, mergeOpts("modes")) : visible;
  await flush("modes" as Namespace, { ...dump, __seq: state().seq } as Record<string, unknown>);
}

// ---------- hydration ----------

export function hydrate(): Promise<void> {
  if (STRICT_STATE && !g.__layersHydrated) {
    // STRICT_STATE (the empty world, the owner service): a hydrate that FAILS is forgotten, so the next call retries —
    // the read is fail-closed (loadAllStrict) and a memoised failure would otherwise keep the process down until a
    // restart
    const attempt = hydrateOnce();
    g.__layersHydrated = attempt;
    attempt.catch(() => {
      if (g.__layersHydrated === attempt) g.__layersHydrated = null;
    });
    return attempt;
  }
  return hydrateOnce();
}

function hydrateOnce(): Promise<void> {
  g.__layersHydrated ??= (async () => {
    const loaded = STRICT_STATE ? await loadAllStrict() : await loadAll();
    const s = state();
    // LAYERS_WORLD=empty: the allowlist the partition below checks every stored entry against — read ONCE, before
    // any namespace loads (an unreadable keystore throws here, loudly: no partition is better than a wrong one)
    const real = EMPTY_WORLD ? new Set(realPersonaIds()) : null;
    if (EMPTY_WORLD) worldHidden().clear();
    if (real) g.__layersWorldReal = real;
    const hiddenIds = EMPTY_WORLD ? new Set<string>() : null;
    for (const [ns, serializer] of Object.entries(SERIALIZERS) as [Namespace, Serializer][]) {
      const entries = loaded[ns];
      if (!entries) continue;
      // whole-sealed, per-record sealed, or legacy plaintext — unsealAny knows the three shapes. Gate 5
      // (attack-custody-1 #14): once THIS device has sealed a namespace, a plaintext shape for it is a hostile or
      // corrupt validator, never a legacy read — refuse it rather than load unauthenticated state.
      const { sealedNamespaces } = await import("@/lib/adapters/mock/persist");
      const looksSealed = (e: Record<string, unknown>) => {
        const w = e["__whole"] as { ct?: unknown } | undefined;
        if (w && typeof w === "object" && typeof w.ct === "string") return true;
        const vals = Object.values(e);
        return vals.length > 0 && vals.every((v) => v && typeof v === "object" && typeof (v as { ct?: unknown }).ct === "string");
      };
      if (sealedNamespaces().has(ns) && !looksSealed(entries as Record<string, unknown>))
        throw new Error(`hydrate: namespace ${ns} came back in plaintext after this device sealed it — refusing`);
      const unsealed = unsealAny(ns, entries as Record<string, unknown>);
      const { __seq, ...rest } = unsealed as Record<string, unknown> & { __seq?: number };
      if (typeof __seq === "number") s.seq = Math.max(s.seq, __seq);
      if (real) {
        // LAYERS_WORLD=empty — THE PARTITION (lib/world.ts): only entries that name nothing but this device's real
        // personas load; the rest are held aside verbatim and merged back into every write of this namespace
        const { visible, hidden } = partitionNamespace(ns, rest, real);
        if (hidden) {
          worldHidden().set(ns, hidden);
          for (const k of hiddenKeys(hidden)) hiddenIds!.add(k);
        }
        serializer.load(s, visible);
      } else {
        serializer.load(s, rest);
      }
    }
    if (hiddenIds) g.__layersWorldHiddenKeys = hiddenIds;
    clearFlushCache();
    // STRICT_STATE: the stored state has been READ (and, in the empty world, partitioned) — from here on a write can
    // carry it back
    if (STRICT_STATE) g.__layersWorldLoaded = true;
    adoptRealPersonas();
    // Fixture grant graph. Idempotent; runs after load so persisted grants win.
    try {
      // LAYERS_WORLD=empty: none of the DEMO seeders run (lib/world.ts layer 2) — every one of them writes the
      // bank's world (its personas, its grants, its marketplace) into the store. A seeder added to this block later
      // is skipped the same way. The replays and the product lenses below are not demo content and still run.
      if (!EMPTY_WORLD) {
      const { seedGrantGraph } = await import("@/lib/identity/seedGrants");
      if (!deviceViewer) seedGrantGraph(); // the fixture grant graph is the seeded viewer's, never a visitor's
      const { seedPrivateWorld } = await import("@/lib/private/seed");
      if (!deviceViewer) seedPrivateWorld(); // the fixture private world is the rig's, never a visitor's
      const { backfillSeededFollows } = await import("@/lib/eventlog/log");
      await backfillSeededFollows(SEED_VIEWER.activePersonaId);
      const { seedAlgoMarketplace } = await import("@/lib/algo/seed");
      seedAlgoMarketplace();
      const { seedCuratorFeeds } = await import("@/lib/curators/annotations");
      seedCuratorFeeds();
      const { seedIssuanceDraft } = await import("@/lib/curators/issuance");
      await seedIssuanceDraft();
      const { seedRefutations } = await import("@/lib/refutation/edges");
      seedRefutations();
      const { seedFilterPack } = await import("@/lib/packs/service");
      seedFilterPack();
      const { seedDestinationBindings } = await import("@/lib/crosspost/destinations");
      seedDestinationBindings();
      const { seedInfoFi } = await import("@/lib/market/infofi");
      await seedInfoFi();
      }
      // UX Gate 3: postByHash is a plain module Map, never itself
      // persisted — a real restart rebuilds it from SEED_POSTS only. Replay
      // every persisted coldResolved entry back into it so the (separately
      // persisted) readwise schedules can still resolve their source.
      const { replayColdResolvedPosts } = await import("@/lib/x/coldstore");
      replayColdResolvedPosts();
      // MEGA PASS 2 Gate 5: DM-sourced items live in the vault (xImportedPrivate); their synthetic posts are rebuilt here
      const { replayDmPosts } = await import("@/lib/x/inbox");
      replayDmPosts();
      // MEGA PASS 2 Gate 1: seeded stake history (signed by the fixture personas, through the product path, idempotent)
      // — demo content: never under LAYERS_WORLD=empty
      if (!EMPTY_WORLD) {
        const { seedStakes } = await import("@/lib/influence/seed");
        await seedStakes();
      }
      // MEGA PASS 2 Gate 2: the canonical lens and the seeded dwell-heavy lens (PRODUCT lenses authored by "layers",
      // not demo content — they stay in the empty world)
      const { seedLenses } = await import("@/lib/lens/service");
      await seedLenses();
    } catch {
      /* seeding is best-effort; absence shows up as hidden linkage */
    }
    // PERSONA LAUNCH P2 (BYX G3): the X shelf is a chunked sealed document outside this store. Read it ONCE here so the
    // synchronous readers (the feed's resurfaced cards, search) see it — and never let it fail the hydrate: an
    // unreadable shelf leaves them skipping it, and the profile, which awaits the shelf itself, says why.
    try {
      const { loadShelf } = await import("@/lib/x/shelf");
      await loadShelf();
    } catch {
      /* the profile view reports an unreadable shelf; nothing else depends on it */
    }
  })();
  return g.__layersHydrated;
}

/** Developer pane: seed reset — drops mutable state back to seed baseline. */
export async function resetState() {
  // LAYERS_WORLD=empty: REFUSED. A reset wipes every stored namespace of this device (wipeAll) and purges forked
  // personas from the keystore — on the owner service that is the owner's real records, not a seed to return to.
  // (app/api/dev refuses the action first; this is the store's own refusal, for any other caller.)
  if (EMPTY_WORLD) throw new Error("resetSeed is refused under LAYERS_WORLD=empty: it wipes stored state and purges keystore personas");
  // FC pass: LIVE-mode write-ledger entries survive a seed reset. They are
  // calendar-day facts about the real public network — wiping them would
  // refresh the daily write caps mid-day and destroy check-before-retry
  // receipts for casts that genuinely exist out there. FIXTURE entries are
  // seed state like everything else and reset with it (the fc3 suite
  // depends on that).
  const liveFcWrites = [...(g.__layersMockState?.fcWrites?.values() ?? [])].filter(
    (e) => e.mode === "live"
  );
  // MULTI-FID Gate 5 (attack-fid-2 #9, attack-fid-3 #2): the LIVE fid spend entries and the LIVE persona↔fid records are
  // facts about real money and real accounts — a reset that forgot them would refresh the $10 cap and the
  // two-account limit and destroy the only copy of each account's signer. Read BEFORE the wipe; a failed read
  // refuses the reset (fail closed) rather than wiping what it could not see.
  const liveSpend = [...(g.__layersMockState?.xSpend?.values() ?? [])].filter((e) => e.mode === "live");
  const { liveFidRecordsSnapshot, reseedAfterReset } = await import("@/lib/fc/personaFid");
  const liveFids = await liveFidRecordsSnapshot();
  g.__layersMockState = freshState();
  clearFlushCache();
  // PERSONA LAUNCH P2 (BYX G2): the X documents (shelf, archive, follows) are module-owned sealed documents with their
  // own cache; the wipe below empties the validator's copy, so the cache goes with the seed — and with them the
  // staged (unsaved) import lanes and the downloaded X index copy (a rig suite clears the validator's index and must
  // not be answered from this process's copy of it)
  resetXDocsCache();
  try {
    const { resetImportStaging } = await import("@/lib/x/importer");
    resetImportStaging();
    const { resetXIndexCache } = await import("@/lib/x/indexClient");
    resetXIndexCache();
  } catch {
    /* best effort, like the rest of the reset's module caches */
  }
  // the render layer's fixture store (local casts, reaction toggles) lives
  // in its own global and must reset WITH the seed, or local casts
  // accumulate for the process lifetime across resets
  const { resetLocalStore } = await import("@/lib/data");
  resetLocalStore();
  // UX Gate 1/2: ephemeral session state (mode-override markers, later the
  // undo stack) is scoped to a session — a reset starts a new one.
  const { resetEphemeralSession } = await import("@/lib/session/ephemeral");
  resetEphemeralSession();
  // Re-seed the fixture grant graph. resetState marks hydration as already
  // done, so without this the graph is never rebuilt and every seeded
  // linkage silently becomes hidden — which reads as a block fan-out bug.
  try {
    const { seedGrantGraph } = await import("@/lib/identity/seedGrants");
    if (!deviceViewer) seedGrantGraph(); // the fixture grant graph is the seeded viewer's, never a visitor's
    const { seedPrivateWorld } = await import("@/lib/private/seed");
    if (!deviceViewer) seedPrivateWorld(); // the fixture private world is the rig's, never a visitor's
    const { backfillSeededFollows } = await import("@/lib/eventlog/log");
    await backfillSeededFollows(SEED_VIEWER.activePersonaId);
    const { seedAlgoMarketplace } = await import("@/lib/algo/seed");
    seedAlgoMarketplace();
    const { seedCuratorFeeds } = await import("@/lib/curators/annotations");
    seedCuratorFeeds();
    const { seedIssuanceDraft } = await import("@/lib/curators/issuance");
    await seedIssuanceDraft();
    const { seedRefutations } = await import("@/lib/refutation/edges");
    seedRefutations();
    const { seedFilterPack } = await import("@/lib/packs/service");
    seedFilterPack();
    const { seedDestinationBindings } = await import("@/lib/crosspost/destinations");
    seedDestinationBindings();
    const { seedInfoFi } = await import("@/lib/market/infofi");
    await seedInfoFi();
  } catch {
    /* best effort */
  }
  // Forked personas are real keystore entries and real entries in the render
  // maps. A seed reset has to unmake both, or every demo run accretes another
  // abandoned identity and later runs fork on top of stale state.
  try {
    const { purgeForkedPersonas, purgeFixtureConnectPersonas, purgeFixtureSiwfPersonas } = await import("@/lib/identity/keystore");
    // CONNECT MAIN review (UXC-13): the persona a FIXTURE main-account connection minted goes with the fixture record
    // (seed state, wiped below) — the same reset contract as a fork's. PERSONA LAUNCH P1 (SIWF's diff): and the persona
    // a FIXTURE Sign in with Farcaster minted, the same way.
    for (const id of [...purgeForkedPersonas(), ...purgeFixtureConnectPersonas(), ...purgeFixtureSiwfPersonas()]) {
      const p = personaById.get(id);
      if (p) personaByHandle.delete(p.handle);
      personaById.delete(id);
    }
    // and the fixture network's signers with it (an in-process stand-in for Neynar; a restart forgets them anyway)
    const { resetConnectFixture } = await import("@/lib/fc/connect");
    resetConnectFixture();
  } catch {
    /* best effort */
  }
  // UX Gate 3: resolved cold-storage items inject synthetic entries into
  // postByHash (same module-level Map the seeded posts live in) — a reset
  // that leaves those standing would let resolved bookmark text survive a
  // seed reset with zero coldResolved state to explain it.
  try {
    const { purgeColdResolvedPosts } = await import("@/lib/x/coldstore");
    purgeColdResolvedPosts();
    // MEGA PASS 2 Gate 5: the DM-sourced synthetic posts go with the seed too
    const { purgeDmPosts } = await import("@/lib/x/inbox");
    purgeDmPosts();
  } catch {
    /* best effort */
  }
  await wipeAll();
  // PERSONA LAUNCH P2 (review W1-R3): AGAIN after the wipe. A read that ran between the first reset and the wipe (a page
  // still polling its profile) cached the pre-wipe documents and their generations; with the save path's live-manifest
  // check that copy would now be refused as a rollback ("save 0 served after save N") instead of silently re-sealing
  // the wiped shelf into the fresh seed. The epoch bump also keeps any read still in flight from caching.
  resetXDocsCache();
  // STRICT_STATE (the owner service with the flag off): the stored state is now KNOWN — wiped — so the writes below
  // (and every later one) replace nothing this process has not seen
  if (STRICT_STATE) g.__layersWorldLoaded = true;
  if (liveFcWrites.length) {
    for (const e of liveFcWrites) g.__layersMockState!.fcWrites.set(e.id, e);
    await persistNs("fcWrites");
  }
  if (liveSpend.length) {
    // spend-ledger writes stay pinned to lib/x/spend.ts (x3 #7): the ledger restores its own live entries
    const { restoreLiveSpendEntries } = await import("@/lib/x/spend");
    await restoreLiveSpendEntries(liveSpend);
  }
  if (liveFids.length) await reseedAfterReset(liveFids);
  // MEGA PASS 2 Gate 1: the influence namespace was wiped with the rest and the validator dropped its fixture stake
  // rows — drop the in-process copy and re-seed the history (signed, idempotent). Best effort, like every seed.
  try {
    const { resetInfluenceCache } = await import("@/lib/influence/allowance");
    resetInfluenceCache();
    const { seedStakes, resetStakeSeedMarker } = await import("@/lib/influence/seed");
    resetStakeSeedMarker();
    await seedStakes();
    const { seedLenses } = await import("@/lib/lens/service");
    await seedLenses();
  } catch {
    /* best effort */
  }
  g.__layersHydrated = Promise.resolve();
}

/**
 * Review WE-1: ids are unique ACROSS PROCESSES. The counter used to restart at 0 with every process (nothing persisted
 * it — persistSeq had no caller), so the n-th claim, rule, folder, channel, mode or settlement of every boot got the
 * SAME id as the n-th of the boot before, and the callers `.set(id, …)` without an existence check: a restart quietly
 * overwrote the owner's earlier record (and, under LAYERS_WORLD=empty, could take a hidden record's key). Three
 * guards, each sufficient on its own:
 *   - the counter is PERSISTED (persistNs carries `__seq` on every whole-sealed write; hydrate restores the max), so
 *     a restart continues the count;
 *   - ID_EPOCH — the module's load time in base36 (8 chars, fixed width until 2059) plus 4 random chars — is appended
 *     to every id, so two processes never draw the same id even when the count did not persist (a vault-only write,
 *     a restart before any write);
 *   - under LAYERS_WORLD=empty an id that equals a key the partition HID is skipped (the record under that key is
 *     stored and invisible; a new record must never take it).
 * The counter keeps ids ordered within a process.
 */
const ID_EPOCH = Date.now().toString(36).padStart(8, "0").slice(-8) + (Math.random().toString(36).slice(2, 6) + "0000").slice(0, 4);
/** the width of ID_EPOCH — the empty-world suite reads the epoch back off an id to show it differs across restarts */
export const ID_EPOCH_LENGTH = 12;
export function nextId(prefix: string): string {
  const s = state();
  const taken = g.__layersWorldHiddenKeys;
  for (;;) {
    s.seq += 1;
    const id = `${prefix}_${s.seq.toString(36)}${(s.seq * 7919).toString(36)}${ID_EPOCH}`;
    if (!taken || !taken.has(id)) return id;
    console.error(`[world] nextId skipped an id that equals a HIDDEN record's key (${prefix}) — the stored record keeps its key`);
  }
}

/** BROWSER KEYSTORE PASS Gate 1 stage 3: in the browser the seeded viewer is not an identity — the device rewrites this
 * object into ITS OWN viewer at boot (its minted personas, its root, a fid of its own), before any route runs. The rig
 * never calls this; there the seeded viewer stays what the seed says (docs/custody-model.md, rig-only list). */
let deviceViewer = false;

/** BROWSER KEYSTORE PASS Gate 2: after the device installs a different seed (unlock, import), the store it holds is
 * the previous root's. Discard it and hydrate again under the new root. Device only; the rig never calls this. */
export async function reloadForDevice(): Promise<void> {
  g.__layersMockState = freshState();
  g.__layersHydrated = undefined;
  clearFlushCache();
  // PERSONA LAUNCH P2 (BYX G2): the X documents are the previous root's too, and so are the staged import lanes
  resetXDocsCache();
  const { resetImportStaging } = await import("@/lib/x/importer");
  resetImportStaging();
  const { resetLocalStore } = await import("@/lib/data");
  resetLocalStore();
  const { resetEphemeralSession } = await import("@/lib/session/ephemeral");
  resetEphemeralSession();
}
export function setDeviceViewer(v: { fid: number; rootId: string; personas: string[]; activePersonaId: string }): void {
  deviceViewer = true;
  SEED_VIEWER.fid = v.fid;
  SEED_VIEWER.rootId = v.rootId;
  SEED_VIEWER.personas = v.personas;
  SEED_VIEWER.activePersonaId = v.activePersonaId;
  SEED_VIEWER.followingPersonaIds = [];
  SEED_VIEWER.likedPostHashes = [];
  SEED_VIEWER.bookmarkedPostHashes = [];
}
